    def solve(self):
        # Tracy has a wire 4 feet long
        total_feet = 4

        # Convert total length to inches (since 1 foot = 12 inches)
        total_inches = total_feet * 12  # 48 inches

        # Length of each piece in inches
        piece_length_inches = 6

        # Calculate the number of pieces
        number_of_pieces = total_inches // piece_length_inches

        return number_of_pieces

